import { useCallback, useEffect, useState, type ReactNode } from 'react';
import { Link, useParams } from 'react-router';
import { AppShell } from '../components/Navigation';
import { Btn, SectionHeader, StatusBadge } from '../components/UI';
import { acceptAiTeamProposal, cancelProjectWorkRequest, createProjectWorkRequest, createUserProject, getSettings, getUserProject, getUserProjectFile, listAiTeamDiscussions, listAiTeamProposals, listUserProjects, pauseUserProjectRun, rejectAiTeamProposal, requestAiTeamDiscussion, requestAiTeamProposal, resumeUserProjectRun, retryUserProjectRun, scheduleUserProjectRuns, startUserProjectRun, updateUserProjectTeam, type AiTeamDiscussion, type AiTeamProposal, type UserProject, type UserProjectView, type UserProjectWorkspaceDiffHunk, type UserProjectWorkspaceDiffLine, type UserProjectWorkspaceFilePreview, UserApiError } from '../api/userApi';
import { userFacingError } from '../errorMessage';
import { useUser } from '../store/useUser';
import { formatWorldDate } from '../domain/worldState';

function message(error: unknown): string { return userFacingError(error, '프로젝트 요청을 처리하지 못했습니다.'); }
function date(value: string, timezone?: string): string { return formatWorldDate(timezone, value); }
type ProjectListItem = UserProject & { runtime: UserProjectView["runtime"] };
function projectRuntimeSummary(runtime: ProjectListItem["runtime"]): string {
  if (runtime.status === 'completed') return `Run 완료${runtime.runId ? ` · ${runtime.runId}` : ''}`;
  if (runtime.status === 'running') return `Run 실행 중${runtime.runId ? ` · ${runtime.runId}` : ''}`;
  if (runtime.status === 'waiting') return runtime.blocker ?? 'Run 실행 대기 중';
  if (runtime.status === 'failed') return runtime.blocker ?? 'Run 실행 실패';
  if (runtime.status === 'not-started') return '실행된 Run 없음';
  return runtime.blocker ?? 'Run 상태 확인 불가';
}

export function ProjectList() {
  const profile = useUser(); const timezone = profile.status === 'ready' ? profile.timezone : undefined;
  const [projects, setProjects] = useState<ProjectListItem[]>([]); const [loading, setLoading] = useState(true); const [showCreate, setShowCreate] = useState(false); const [name, setName] = useState(''); const [objective, setObjective] = useState(''); const [purpose, setPurpose] = useState('rapid-prototype'); const [teamMode, setTeamMode] = useState<UserProject['teamMode']>('solo'); const [teamId, setTeamId] = useState(''); const [error, setError] = useState<string | null>(null); const [busy, setBusy] = useState(false);
  const refresh = useCallback(async () => { setLoading(true); setError(null); try { const listed = (await listUserProjects()).projects; const hydrated = await Promise.all(listed.map(async (project) => { try { const view = await getUserProject(project.id); return { ...project, runtime: view.runtime }; } catch { return { ...project, runtime: { status: 'unknown', blocker: '프로젝트 실행 상태를 확인할 수 없습니다.' } }; } })); setProjects(hydrated); } catch (nextError) { setError(message(nextError)); } finally { setLoading(false); } }, []);
  useEffect(() => { void refresh(); }, [refresh]);
  const create = async () => { if (!name.trim() || !objective.trim()) { setError('프로젝트 이름과 목적을 입력하세요.'); return; } setBusy(true); setError(null); try { const result = await createUserProject({ name: name.trim(), objective: objective.trim(), purpose, teamMode, ...((teamMode === 'human' || teamMode === 'mixed') && teamId.trim() ? { teamId: teamId.trim() } : {}) }); setProjects((current) => [{ ...result.project, runtime: { status: 'not-started' } }, ...current]); setName(''); setObjective(''); setTeamId(''); setShowCreate(false); } catch (nextError) { setError(message(nextError)); } finally { setBusy(false); } };
  return <AppShell><div className="p-6 md:p-8" style={{ fontFamily: 'var(--font-body)' }}><SectionHeader title="프로젝트 작업실" subtitle="실제 사용자 프로젝트와 실행 근거를 확인합니다." action={<div className="flex gap-2"><Btn variant="secondary" onClick={() => void refresh()} disabled={loading || busy}>새로고침</Btn><Btn variant="primary" onClick={() => setShowCreate((current) => !current)} disabled={busy}>{showCreate ? '닫기' : '+ 새 프로젝트'}</Btn></div>} />{error && <div role="alert" className="mb-5 rounded-xl border-2 border-rose-200 bg-rose-50 p-4 text-sm font-semibold text-rose-700">{error}</div>}{showCreate && <section className="card-game mb-6 max-w-2xl p-5"><h3 className="mb-4 text-lg font-black text-slate-900">프로젝트 생성</h3><div className="grid gap-3"><input aria-label="프로젝트 이름" value={name} onChange={(event) => setName(event.target.value)} placeholder="프로젝트 이름" className="rounded-xl border-2 border-blue-100 px-3 py-2.5 text-sm" /><textarea aria-label="프로젝트 목적" value={objective} onChange={(event) => setObjective(event.target.value)} placeholder="무엇을 만들고 검증할지 적어주세요." rows={3} className="rounded-xl border-2 border-blue-100 px-3 py-2.5 text-sm" /><div className="grid gap-3 md:grid-cols-2"><label className="text-sm font-semibold text-slate-700">목적<select value={purpose} onChange={(event) => setPurpose(event.target.value)} className="mt-1 w-full rounded-xl border-2 border-blue-100 px-3 py-2.5"><option value="rapid-prototype">빠른 프로토타입</option><option value="operational-service">운영 서비스</option><option value="portfolio">포트폴리오</option><option value="existing-project-improvement">기존 프로젝트 개선</option></select></label><label className="text-sm font-semibold text-slate-700">팀 구성<select value={teamMode} onChange={(event) => setTeamMode(event.target.value as UserProject['teamMode'])} className="mt-1 w-full rounded-xl border-2 border-blue-100 px-3 py-2.5"><option value="solo">솔로</option><option value="ai">AI 팀</option><option value="human">사람 팀</option><option value="mixed">혼합 팀</option></select></label></div>{teamMode === 'human' || teamMode === 'mixed' ? <input aria-label="팀 ID" value={teamId} onChange={(event) => setTeamId(event.target.value)} placeholder="참여할 팀 ID" className="rounded-xl border-2 border-blue-100 px-3 py-2.5 text-sm" /> : null}<p className="text-xs text-slate-400">팀 ID를 입력하면 팀 멤버십이 프로젝트 읽기 권한에 적용됩니다.</p><Btn variant="mint" onClick={() => void create()} disabled={busy}>프로젝트 저장</Btn></div></section>}<div className="mb-5 rounded-xl border-2 border-amber-200 bg-amber-50 p-4 text-sm text-amber-800">프로젝트 실행 결과는 실제 Runtime/Agent가 연결되고 검증된 경우에만 성공으로 표시됩니다. 연결되지 않은 실행은 대기 상태로 보존됩니다.</div>{loading ? <p className="text-sm text-slate-500">프로젝트를 불러오는 중…</p> : projects.length === 0 ? <div className="card-game p-6 text-sm text-slate-500">아직 저장된 프로젝트가 없습니다. 프로젝트를 생성하면 사용자별 작업 공간이 만들어집니다.</div> : <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">{projects.map((project) => <Link key={project.id} to={`/projects/${project.id}`} className="card-game block p-5 no-underline transition hover:-translate-y-0.5"><div className="flex items-start justify-between gap-3"><div><h3 className="font-black text-slate-900">{project.name}</h3><p className="mt-1 line-clamp-3 text-sm text-slate-600">{project.objective}</p></div><StatusBadge status={runtimeStatus(project.runtime.status)} /></div><p className="mt-3 text-xs font-semibold text-slate-500">{projectRuntimeSummary(project.runtime)}</p><div className="mt-4 flex flex-wrap gap-2"><span className="rounded-full bg-blue-50 px-2 py-1 text-xs font-semibold text-blue-700">{project.purpose}</span><span className="rounded-full bg-violet-50 px-2 py-1 text-xs font-semibold text-violet-700">{project.teamMode}</span></div><p className="mt-4 text-xs text-slate-400">저장 {date(project.createdAt, timezone)}</p></Link>)}</div>}</div></AppShell>;
}

function runtimeStatus(status: string): 'running' | 'success' | 'warning' | 'pending' | 'error' | 'unknown' { if (status === 'completed') return 'success'; if (status === 'running') return 'running'; if (status === 'waiting') return 'warning'; if (status === 'failed') return 'error'; if (status === 'not-started') return 'pending'; return 'unknown'; }

function TeamTransition({ view, projectId, busy, onChanged, onError }: { view: UserProjectView; projectId: string; busy: boolean; onChanged: () => Promise<void>; onError: (error: unknown) => void }) {
  const [teamMode, setTeamMode] = useState<UserProject['teamMode']>(view.project.teamMode); const [teamId, setTeamId] = useState(view.project.teamId ?? '');
  useEffect(() => { setTeamMode(view.project.teamMode); setTeamId(view.project.teamId ?? ''); }, [view.project.teamMode, view.project.teamId]);
  const save = async () => { try { await updateUserProjectTeam(projectId, { teamMode, ...(teamMode === 'human' || teamMode === 'mixed' ? { teamId: teamId.trim() } : {}) }); await onChanged(); } catch (error) { onError(error); } };
  return <section className="card-game p-5"><h2 className="mb-2 text-lg font-black text-slate-900">진행 중 팀 구성</h2><p className="mb-4 text-sm text-slate-600">프로젝트를 중단하지 않고 솔로·AI·사람·혼합 팀 사이에서 구성할 수 있습니다.</p><div className="grid gap-3 md:grid-cols-[1fr_1fr_auto]"><label className="text-sm font-semibold text-slate-700">팀 모드<select aria-label="진행 중 팀 모드" value={teamMode} onChange={(event) => setTeamMode(event.target.value as UserProject['teamMode'])} className="mt-1 w-full rounded-xl border-2 border-blue-100 px-3 py-2.5"><option value="solo">솔로</option><option value="ai">AI 팀</option><option value="human">사람 팀</option><option value="mixed">혼합 팀</option></select></label><label className="text-sm font-semibold text-slate-700">팀 ID{teamMode === 'human' || teamMode === 'mixed' ? <input aria-label="진행 중 팀 ID" value={teamId} onChange={(event) => setTeamId(event.target.value)} placeholder="팀 ID" className="mt-1 w-full rounded-xl border-2 border-blue-100 px-3 py-2.5" /> : <span className="mt-1 block rounded-xl bg-slate-50 px-3 py-2.5 text-slate-400">팀 모드에서 필요</span>}</label><Btn variant="mint" onClick={() => void save()} disabled={busy || ((teamMode === 'human' || teamMode === 'mixed') && !teamId.trim())}>구성 저장</Btn></div></section>;
}

const roleLabels: Record<string, string> = {
  orchestrator: '조율', planning: '기획', frontend: '프론트엔드', backend: '백엔드',
  'design-system': '디자인 시스템', review: '리뷰', qa: 'QA', documentation: '문서화',
  user: '사용자 검토', governance: '운영 거버넌스',
};

function roleLabel(role: string): string { return roleLabels[role] ?? role; }

function ExecutionProfilePanel({ view }: { view: UserProjectView }) {
  const profile = view.workspace.purposeSelection?.profile;
  if (!profile) {
    return <section className="card-game p-5"><h2 className="mb-2 text-lg font-black text-slate-900">AI 팀 역할</h2><p className="text-sm text-slate-500">저장된 실행 프로필이 없습니다. 역할을 임의로 추정하지 않습니다.</p></section>;
  }
  return <section className="card-game p-5">
    <div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-lg font-black text-slate-900">AI 팀 역할</h2><p className="mt-1 text-sm text-slate-600">프로젝트 목적에 저장된 역할 분담과 실행 가능 범위를 표시합니다.</p></div><span className="rounded-full bg-blue-50 px-3 py-1 text-xs font-bold text-blue-700">{profile.verificationStages.join(' · ')}</span></div>
    {profile.koreanSummary && <p className="mt-4 rounded-xl bg-slate-50 p-3 text-sm text-slate-600">{profile.koreanSummary}</p>}
    <div className="mt-4 grid gap-4 md:grid-cols-2">
      <div><h3 className="mb-2 text-xs font-black uppercase tracking-wide text-emerald-700">실행 어댑터</h3><div className="flex flex-wrap gap-2">{profile.executableRoles.length === 0 ? <span className="text-sm text-slate-500">현재 등록된 실행 역할 없음</span> : profile.executableRoles.map((role) => <span key={role} className="rounded-full bg-emerald-50 px-3 py-1.5 text-sm font-semibold text-emerald-800">{roleLabel(role)}</span>)}</div></div>
      <div><h3 className="mb-2 text-xs font-black uppercase tracking-wide text-amber-700">계획 상태</h3><div className="flex flex-wrap gap-2">{profile.plannedRoles.length === 0 ? <span className="text-sm text-slate-500">계획 상태 역할 없음</span> : profile.plannedRoles.map((role) => <span key={role} className="rounded-full bg-amber-50 px-3 py-1.5 text-sm font-semibold text-amber-800">{roleLabel(role)}</span>)}</div></div>
    </div>
    <p className="mt-4 text-xs text-slate-400">검증 단계: {profile.verificationStages.join(', ')} · 문서화 {profile.documentationRequired ? '필수' : '선택'}</p>
  </section>;
}

function ProjectLifecycleColumn({ title, items }: { title: string; items: UserProjectView['lifecycle']['artifacts'] }) {
  const profile = useUser(); const timezone = profile.status === 'ready' ? profile.timezone : undefined;
  return <section className="rounded-xl border-2 border-slate-100 bg-white p-4">
    <div className="flex items-center justify-between gap-3"><h3 className="font-black text-slate-900">{title}</h3><span className="rounded-full bg-slate-100 px-2 py-1 text-xs font-bold text-slate-500">{items.length}</span></div>
    {items.length === 0 ? <p className="mt-3 text-sm text-slate-500">아직 검증된 증거가 없습니다.</p> : <div className="mt-3 space-y-2">{items.map((item) => <div key={item.id} className="rounded-lg bg-slate-50 p-3"><p className="text-xs font-black uppercase tracking-wide text-blue-700">{item.kind} · {item.stage}</p><p className="mt-1 text-sm font-semibold text-slate-800">{item.summary}</p><p className="mt-1 text-xs text-slate-400">{date(item.recordedAt, timezone)} · Run {item.runId}</p>{item.provider && <p className="mt-1 text-xs text-slate-500">provider: {item.provider}</p>}{item.reference && <p className="mt-1 break-all text-xs text-slate-500">reference: {item.reference}</p>}</div>)}</div>}
  </section>;
}

function ProjectLifecyclePanel({ view }: { view: UserProjectView }) {
  return <section className="card-game p-5"><div className="mb-4"><h2 className="text-lg font-black text-slate-900">프로젝트 생명주기</h2><p className="mt-1 text-sm text-slate-600">Runtime/Agent가 프로젝트와 Run에 귀속해 기록한 검증 증거만 단계별로 표시합니다.</p></div><div className="grid gap-3 md:grid-cols-3"><ProjectLifecycleColumn title="Artifact" items={view.lifecycle.artifacts} /><ProjectLifecycleColumn title="Revision" items={view.lifecycle.revisions} /><ProjectLifecycleColumn title="Deployment" items={view.lifecycle.deployments} /></div></section>;
}

function ProjectHistoryPanel({ view }: { view: UserProjectView }) {
  const profile = useUser(); const timezone = profile.status === 'ready' ? profile.timezone : undefined;
    return <section className="card-game p-5"><div className="mb-4"><h2 className="text-lg font-black text-slate-900">프로젝트 활동 기록</h2><p className="mt-1 text-sm text-slate-600">프로젝트에 실제로 저장된 작업·연동·실행 기록만 표시합니다. 외부 연동 상태나 성공을 임의로 만들지 않습니다.</p></div>{view.history.length === 0 ? <p className="rounded-xl bg-slate-50 p-4 text-sm text-slate-500">기록된 프로젝트 활동이 없습니다.</p> : <div className="space-y-2">{view.history.map((event) => <article key={event.id} className="rounded-xl border-2 border-slate-100 bg-white p-3"><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-xs font-black uppercase tracking-wide text-blue-700">{event.type}</p><time className="text-xs text-slate-400">{date(event.occurredAt ?? event.at, timezone)}</time></div><p className="mt-1 text-sm font-semibold text-slate-800">{event.summary}</p><div className="mt-1 flex flex-wrap gap-x-3 gap-y-1 text-xs text-slate-500">{event.source && <span>source: {event.source}</span>}{event.action && <span>action: {event.action}</span>}{event.runId && <span>Run: {event.runId}</span>}{event.reference && <span className="break-all">reference: {event.reference}</span>}</div></article>)}</div>}</section>;
}

function ProjectRunEvidenceList({ title, items, empty }: { title: string; items: UserProjectView['observability']['runs'][number]['changedFiles']; empty: string }) {
  const profile = useUser(); const timezone = profile.status === 'ready' ? profile.timezone : undefined;
  return <section className="rounded-xl border-2 border-slate-100 bg-white p-4"><div className="flex items-center justify-between gap-3"><h3 className="font-black text-slate-900">{title}</h3><span className="rounded-full bg-slate-100 px-2 py-1 text-xs font-bold text-slate-500">{items.length}</span></div>{items.length === 0 ? <p className="mt-3 text-sm text-slate-500">{empty}</p> : <div className="mt-3 space-y-2">{items.map((item) => <article key={item.id} className="rounded-lg bg-slate-50 p-3"><p className="text-xs font-black uppercase tracking-wide text-blue-700">{item.kind} · {item.stage}</p><p className="mt-1 text-sm font-semibold text-slate-800">{item.summary}</p><time className="mt-1 block text-xs text-slate-400">{date(item.recordedAt, timezone)}</time></article>)}</div>}</section>;
}

function ProjectRunObservabilityPanel({ view }: { view: UserProjectView }) {
  const profile = useUser(); const timezone = profile.status === 'ready' ? profile.timezone : undefined;
  return <section className="card-game p-5"><div className="mb-4"><h2 className="text-lg font-black text-slate-900">Run 관찰 기록</h2><p className="mt-1 text-sm text-slate-600">실제 Run에 귀속된 검증 증거의 요약만 표시합니다. 기록되지 않은 파일·로그·미리보기는 완료된 것으로 추정하지 않습니다.</p></div>{view.observability.runs.length === 0 ? <p className="rounded-xl bg-slate-50 p-4 text-sm text-slate-500">아직 실행된 Run이 없습니다.</p> : <div className="space-y-5">{view.observability.runs.map((run) => <article key={run.runId} className="rounded-xl border-2 border-blue-100 bg-blue-50/30 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-black text-slate-900">Run {run.runId}</h3><p className="mt-1 text-xs text-slate-500">상태 {run.status}{run.stage ? ` · 단계 ${run.stage}` : ''}</p></div>{run.blocker && <p className="max-w-md text-xs font-semibold text-amber-700">{run.blocker}</p>}</div><div className="mt-4 grid gap-3 md:grid-cols-3"><ProjectRunEvidenceList title="변경 파일" items={run.changedFiles} empty="기록된 파일 변경 증거가 없습니다." /><ProjectRunEvidenceList title="테스트·빌드 결과" items={run.checks} empty="기록된 테스트·빌드 증거가 없습니다." /><ProjectRunEvidenceList title="실행 로그 요약" items={run.logs} empty="기록된 명령 로그 요약이 없습니다." /></div><div className="mt-3 rounded-xl border border-dashed border-slate-200 bg-white p-3"><p className="text-xs font-black uppercase tracking-wide text-slate-500">미리보기</p>{run.preview.status === 'ready' ? <><p className="mt-1 text-sm font-semibold text-emerald-700">기록된 미리보기 주소</p><a className="mt-2 inline-flex max-w-full break-all rounded-lg bg-emerald-50 px-3 py-2 text-sm font-bold text-emerald-800 underline" href={run.preview.url} target="_blank" rel="noreferrer">미리보기 열기</a><p className="mt-1 break-all text-xs text-slate-400">{run.preview.url}{run.preview.provider ? ` · ${run.preview.provider}` : ''} · {date(run.preview.recordedAt, timezone)}</p></> : <><p className="mt-1 text-sm text-slate-600">{run.preview.status === 'not-available' ? '미리보기 주소가 기록되지 않았습니다.' : 'durable Run이 없어 미리보기를 확인할 수 없습니다.'}</p><p className="mt-1 text-xs text-slate-400">{run.preview.blocker}</p></>}</div></article>)}</div>}</section>;
}

function AiTeamProposalPanel({ projectId, teamMode, teamId, proposals, busy, onChanged, onError }: { projectId: string; teamMode: UserProject['teamMode']; teamId?: string; proposals: AiTeamProposal[]; busy: boolean; onChanged: () => Promise<void>; onError: (error: unknown) => void }) {
  const [agentId, setAgentId] = useState(''); const [notice, setNotice] = useState('');
  if (!teamId || (teamMode !== 'ai' && teamMode !== 'mixed')) return null;
  const request = async () => { if (!agentId.trim()) return; try { setNotice(''); await requestAiTeamProposal(projectId, { agentId: agentId.trim(), requestId: 'proposal-' + Date.now().toString(36) }); setNotice('AI 팀 제안 요청을 저장했습니다. Runtime이 없으면 대기 상태로 남습니다.'); setAgentId(''); await onChanged(); } catch (error) { onError(error); } };
  const accept = async (proposalId: string) => { try { setNotice(''); await acceptAiTeamProposal(projectId, proposalId); setNotice('사람 승인으로 작업 요청을 만들었습니다. 실행은 별도 승인 단계입니다.'); await onChanged(); } catch (error) { onError(error); } };
  const reject = async (proposalId: string) => { try { setNotice(''); await rejectAiTeamProposal(projectId, proposalId); setNotice('AI 팀 제안을 거절했습니다.'); await onChanged(); } catch (error) { onError(error); } };
  return <section className='card-game p-5'><div className='flex flex-wrap items-start justify-between gap-3'><div><h2 className='text-lg font-black text-slate-900'>AI 팀 협업 제안</h2><p className='mt-1 text-sm text-slate-600'>AI 팀원은 작업을 제안할 수 있지만, 사람 승인 전에는 Work Request나 실행이 생성되지 않습니다.</p></div><span className='rounded-full bg-amber-50 px-3 py-1 text-xs font-bold text-amber-700'>소유자 승인</span></div><div className='mt-4 flex flex-wrap gap-2'><input aria-label='AI 제안 팀원 ID' value={agentId} onChange={(event) => setAgentId(event.target.value)} placeholder='AI 팀원 ID' className='min-w-48 flex-1 rounded-xl border-2 border-blue-100 px-3 py-2.5 text-sm' /><Btn variant='secondary' onClick={() => void request()} disabled={busy || !agentId.trim()}>AI 제안 요청</Btn></div>{notice && <p role='status' className='mt-3 text-sm text-emerald-700'>{notice}</p>}<div className='mt-5 space-y-3'>{proposals.length === 0 ? <p className='rounded-xl bg-slate-50 p-4 text-sm text-slate-500'>저장된 AI 작업 제안이 없습니다.</p> : proposals.map((proposal) => <article key={proposal.id} className='rounded-xl border-2 border-blue-100 p-4'><div className='flex items-start justify-between gap-3'><div><p className='font-bold text-slate-900'>{proposal.title}</p><p className='mt-1 text-sm text-slate-600'>{proposal.objective}</p></div><span className='rounded-full bg-slate-100 px-2 py-1 text-xs font-bold text-slate-600'>{proposal.status === 'waiting-runtime' ? 'Runtime 대기' : proposal.status === 'proposed' ? '승인 대기' : proposal.status === 'accepted' ? '작업 요청 생성' : '거절됨'}</span></div>{proposal.blocker && <p className='mt-2 text-xs text-amber-700'>{proposal.blocker}</p>}{proposal.acceptanceCriteria.length > 0 && <ul className='mt-3 list-disc pl-5 text-xs text-slate-600'>{proposal.acceptanceCriteria.map((criterion) => <li key={criterion}>{criterion}</li>)}</ul>}{proposal.status === 'proposed' && <div className='mt-3 flex gap-2'><Btn variant='mint' size='sm' onClick={() => void accept(proposal.id)} disabled={busy}>제안 승인</Btn><Btn variant='secondary' size='sm' onClick={() => void reject(proposal.id)} disabled={busy}>제안 거절</Btn></div>}</article>)}</div></section>;
}

function AiTeamDiscussionPanel({ projectId, teamMode, teamId, discussions, busy, onChanged, onError }: { projectId: string; teamMode: UserProject['teamMode']; teamId?: string; discussions: AiTeamDiscussion[]; busy: boolean; onChanged: () => Promise<void>; onError: (error: unknown) => void }) {
  const [agentId, setAgentId] = useState(''); const [question, setQuestion] = useState(''); const [notice, setNotice] = useState('');
  if (!teamId || (teamMode !== 'ai' && teamMode !== 'mixed')) return null;
  const request = async () => { if (!agentId.trim() || !question.trim()) return; try { setNotice(''); await requestAiTeamDiscussion(projectId, { agentId: agentId.trim(), requestId: 'discussion-' + Date.now().toString(36), question: question.trim() }); setNotice('AI 기술 토론 요청을 저장했습니다. Runtime이 없으면 대기 상태로 남습니다.'); setQuestion(''); await onChanged(); } catch (error) { onError(error); } };
  return <section className='card-game p-5'><div className='flex flex-wrap items-start justify-between gap-3'><div><h2 className='text-lg font-black text-slate-900'>AI 기술 토론</h2><p className='mt-1 text-sm text-slate-600'>기존 프로젝트 맥락을 바탕으로 AI 팀원의 설명·대안·위험을 확인합니다. 토론만으로 작업 실행은 생성되지 않습니다.</p></div><span className='rounded-full bg-blue-50 px-3 py-1 text-xs font-bold text-blue-700'>Runtime 경계</span></div><div className='mt-4 grid gap-2 md:grid-cols-[minmax(12rem,0.35fr)_1fr_auto]'><input aria-label='AI 토론 팀원 ID' value={agentId} onChange={(event) => setAgentId(event.target.value)} placeholder='AI 팀원 ID' className='rounded-xl border-2 border-blue-100 px-3 py-2.5 text-sm' /><textarea aria-label='토론 질문' value={question} onChange={(event) => setQuestion(event.target.value)} placeholder='예: 이 API 경계의 위험과 대안을 설명해 주세요.' rows={2} className='rounded-xl border-2 border-blue-100 px-3 py-2.5 text-sm' /><Btn variant='secondary' onClick={() => void request()} disabled={busy || !agentId.trim() || !question.trim()}>토론 요청</Btn></div>{notice && <p role='status' className='mt-3 text-sm text-emerald-700'>{notice}</p>}<div className='mt-5 space-y-3'>{discussions.length === 0 ? <p className='rounded-xl bg-slate-50 p-4 text-sm text-slate-500'>저장된 AI 기술 토론이 없습니다.</p> : discussions.map((discussion) => <article key={discussion.id} className='rounded-xl border-2 border-blue-100 p-4'><div className='flex items-start justify-between gap-3'><div><p className='font-bold text-slate-900'>{discussion.question}</p><p className='mt-1 text-xs text-slate-500'>{discussion.agentId} · {roleLabel(discussion.assignmentRole)}</p></div><span className='rounded-full bg-slate-100 px-2 py-1 text-xs font-bold text-slate-600'>{discussion.status === 'waiting-runtime' ? 'Runtime 대기' : '답변 확인'}</span></div>{discussion.answer && <p className='mt-3 rounded-xl bg-blue-50 p-3 text-sm leading-6 text-slate-700'>{discussion.answer}</p>}{discussion.blocker && <p className='mt-2 text-xs text-amber-700'>{discussion.blocker}</p>}{discussion.keyPoints.length > 0 && <div className='mt-3'><p className='text-xs font-black text-slate-500'>핵심 포인트</p><ul className='mt-1 list-disc pl-5 text-xs text-slate-600'>{discussion.keyPoints.map((item) => <li key={item}>{item}</li>)}</ul></div>}{discussion.alternatives.length > 0 && <p className='mt-2 text-xs text-slate-600'><span className='font-bold'>대안:</span> {discussion.alternatives.join(' · ')}</p>}{discussion.risks.length > 0 && <p className='mt-2 text-xs text-amber-700'><span className='font-bold'>위험:</span> {discussion.risks.join(' · ')}</p>}</article>)}</div></section>;
}

type WorkspaceTab = 'overview' | 'tasks' | 'ai' | 'evidence';
const workspaceTabs: Array<{ id: WorkspaceTab; label: string; description: string }> = [
  { id: 'overview', label: '개요', description: '팀 구성과 실행 프로필' },
  { id: 'tasks', label: '작업', description: '작업 요청과 프로젝트 구조' },
  { id: 'ai', label: 'AI 협업', description: 'AI 제안과 기술 토론' },
  { id: 'evidence', label: '실행·증거', description: 'Runtime 결과와 활동 근거' },
];

function MobileWorkspaceTabs({ activeTab, onChange }: { activeTab: WorkspaceTab; onChange: (tab: WorkspaceTab) => void }) {
  return <nav className="md:hidden mb-5 -mx-1 overflow-x-auto pb-1" aria-label="프로젝트 작업실 모바일 메뉴">
    <div role="tablist" aria-label="프로젝트 작업실" className="flex min-w-max gap-2 px-1">
      {workspaceTabs.map((tab) => <button key={tab.id} type="button" role="tab" aria-selected={activeTab === tab.id} aria-label={`${tab.label}: ${tab.description}`} data-workspace-tab={tab.id} onClick={() => onChange(tab.id)} className={`min-h-11 rounded-xl border-2 px-4 py-2 text-sm font-bold transition ${activeTab === tab.id ? 'border-blue-500 bg-blue-600 text-white' : 'border-blue-100 bg-white text-slate-600'}`}>
        {tab.label}
      </button>)}
    </div>
  </nav>;
}

function WorkspacePanel({ tab, activeTab, children }: { tab: WorkspaceTab; activeTab: WorkspaceTab; children: ReactNode }) {
  return <div className={activeTab === tab ? 'block' : 'hidden md:block'} data-workspace-panel={tab}>{children}</div>;
}

function AiCollaborationWorkspace({ projectId, teamMode, teamId, proposals, discussions, busy, onChanged, onError }: { projectId: string; teamMode: UserProject['teamMode']; teamId?: string; proposals: AiTeamProposal[]; discussions: AiTeamDiscussion[]; busy: boolean; onChanged: () => Promise<void>; onError: (error: unknown) => void }) {
  const available = Boolean(teamId && (teamMode === 'ai' || teamMode === 'mixed'));
  if (!available) return <section className="card-game p-5"><h2 className="text-lg font-black text-slate-900">AI 협업</h2><p className="mt-2 text-sm text-slate-600">현재 프로젝트 팀 모드에서는 AI 협업 패널이 활성화되지 않았습니다. 팀 구성을 AI 팀 또는 혼합 팀으로 바꾸면 제안과 기술 토론을 사용할 수 있습니다.</p></section>;
  return <><AiTeamProposalPanel projectId={projectId} teamMode={teamMode} teamId={teamId} proposals={proposals} busy={busy} onChanged={onChanged} onError={onError} /><AiTeamDiscussionPanel projectId={projectId} teamMode={teamMode} teamId={teamId} discussions={discussions} busy={busy} onChanged={onChanged} onError={onError} /></>;
}

function ProjectStructurePanel({ view }: { view: UserProjectView }) {
  return <><section className="card-game p-5"><h2 className="mb-3 text-lg font-black text-slate-900">프로젝트 구조</h2><div className="space-y-2 text-sm">{view.workspace.tree.map((node) => <div key={node.id} className="flex justify-between rounded-lg bg-slate-50 p-3"><span>{node.title}</span><span className="text-slate-400">{node.status} · Run {node.runIds.length}</span></div>)}</div></section><ProjectDependencyPlanner view={view} /><ProjectQueueScheduler view={view} /></>;
}

function ProjectDependencyPlanner({ view }: { view: UserProjectView }) {
  const [title, setTitle] = useState(''); const [objective, setObjective] = useState(''); const [selectedDependencies, setSelectedDependencies] = useState<string[]>([]); const [status, setStatus] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const candidates = view.workRequests.filter((request) => request.status !== 'cancelled');
  const toggle = (requestId: string) => setSelectedDependencies((current) => current.includes(requestId) ? current.filter((item) => item !== requestId) : [...current, requestId]);
  const create = async () => { if (!title.trim() || !objective.trim() || selectedDependencies.length === 0) { setError('작업 제목·목적과 최소 한 개의 선행 작업을 입력하세요.'); return; } setBusy(true); setError(''); setStatus(''); try { await createProjectWorkRequest(view.project.id, { title: title.trim(), objective: objective.trim(), idempotencyKey: `dependency-${Date.now().toString(36)}`, dependencies: selectedDependencies }); setTitle(''); setObjective(''); setSelectedDependencies([]); setStatus('선행 작업이 연결된 작업을 저장했습니다. 프로젝트를 새로고침하면 작업 그래프에 반영됩니다.'); } catch (caught) { setError(message(caught)); } finally { setBusy(false); } };
  return <section className="card-game p-5"><div className="mb-3"><h2 className="text-lg font-black text-slate-900">의존 작업 계획</h2><p className="mt-1 text-sm text-slate-600">선행 작업이 완료되기 전에는 이 작업의 Run이 실행되지 않고 대기 상태로 보존됩니다.</p></div>{candidates.length === 0 ? <p className="rounded-xl bg-slate-50 p-4 text-sm text-slate-500">선행 작업으로 선택할 기존 작업이 없습니다.</p> : <div className="grid gap-3"><input aria-label="의존 작업 제목" value={title} onChange={(event) => setTitle(event.target.value)} placeholder="후속 작업 제목" className="rounded-xl border-2 border-blue-100 px-3 py-2.5 text-sm" /><textarea aria-label="의존 작업 목적" value={objective} onChange={(event) => setObjective(event.target.value)} placeholder="후속 작업의 완료 조건" rows={2} className="rounded-xl border-2 border-blue-100 px-3 py-2.5 text-sm" /><fieldset className="rounded-xl border-2 border-blue-100 p-3"><legend className="px-1 text-xs font-black text-slate-600">선행 작업</legend><div className="space-y-2">{candidates.map((request) => <label key={request.id} className="flex items-center gap-2 text-sm text-slate-700"><input type="checkbox" aria-label={`선행 작업 ${request.title}`} checked={selectedDependencies.includes(request.id)} onChange={() => toggle(request.id)} disabled={busy} />{request.title}<span className="text-xs text-slate-400">({request.status})</span></label>)}</div></fieldset><button type="button" className="rounded-xl bg-slate-800 px-4 py-2.5 text-sm font-bold text-white disabled:opacity-40" onClick={() => void create()} disabled={busy || selectedDependencies.length === 0}>의존 작업 저장</button></div>}{status && <p role="status" className="mt-3 text-sm text-emerald-700">{status}</p>}{error && <p role="alert" className="mt-3 text-sm text-rose-700">{error}</p>}<div className="mt-4 space-y-2">{view.workRequests.filter((request) => (request.dependencies?.length ?? 0) > 0).map((request) => <p key={request.id} className="rounded-lg bg-amber-50 p-3 text-xs text-amber-800">{request.title} · 선행 작업: {request.dependencies?.map((dependency) => view.workRequests.find((candidate) => candidate.id === dependency)?.title ?? dependency).join(', ')}</p>)}</div></section>;
}

function ProjectQueueScheduler({ view }: { view: UserProjectView }) {
  const [maxConcurrent, setMaxConcurrent] = useState('1'); const [approvalPending, setApprovalPending] = useState(false); const [status, setStatus] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const execute = async (approved = false) => { setBusy(true); setError(''); setStatus(''); try { const result = await scheduleUserProjectRuns(view.project.id, { maxConcurrent: Math.max(1, Math.min(8, Number(maxConcurrent) || 1)), ...(approved ? { approved: true } : {}) }); const started = result.results.filter((item) => item.status === 'started' || item.status === 'already-active').length; const waiting = result.results.filter((item) => item.status === 'waiting').length; setApprovalPending(false); setStatus(`큐 처리 결과 · 선택 ${result.selected}개 · 실행 ${started}개 · 대기 ${waiting}개`); } catch (caught) { const text = message(caught); if (text.includes('Build run approval is required')) setApprovalPending(true); else setError(text); } finally { setBusy(false); } };
  const schedule = async () => { try { const settings = (await getSettings()).settings; if (settings.aiApproval.buildRun) { setApprovalPending(true); return; } await execute(false); } catch (caught) { setError(message(caught)); } };
  const queued = view.workRequests.filter((request) => request.status === 'queued').length;
  return <section className="card-game p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-lg font-black text-slate-900">준비된 작업 큐</h2><p className="mt-1 text-sm text-slate-600">선행 조건이 충족된 queued 작업만 선택한 동시성 한도 안에서 처리합니다. 자동 실행이 아니라 사용자가 누르는 명시적 작업입니다.</p></div><span className="rounded-full bg-blue-50 px-3 py-1 text-xs font-bold text-blue-700">대기 {queued}개</span></div><div className="mt-4 flex flex-wrap items-end gap-3"><label className="text-sm font-semibold text-slate-700">최대 동시 실행<select aria-label="최대 동시 실행" value={maxConcurrent} onChange={(event) => setMaxConcurrent(event.target.value)} className="mt-1 block rounded-xl border-2 border-blue-100 px-3 py-2.5"><option value="1">1개</option><option value="2">2개</option><option value="4">4개</option><option value="8">8개</option></select></label><button type="button" className="rounded-xl bg-blue-600 px-4 py-2.5 text-sm font-bold text-white disabled:opacity-40" onClick={() => void schedule()} disabled={busy || queued === 0}>준비된 작업 실행</button></div>{approvalPending && <div className="mt-4 rounded-xl border-2 border-amber-200 bg-amber-50 p-4"><p className="text-sm font-bold text-amber-900">실행 승인 필요</p><p className="mt-1 text-sm text-amber-800">설정에서 Build Run 승인이 켜져 있습니다. 확인하기 전에는 어떤 작업도 Runtime에 전달하지 않습니다.</p><div className="mt-3 flex gap-2"><button type="button" className="rounded-lg bg-amber-700 px-3 py-2 text-xs font-bold text-white" onClick={() => void execute(true)} disabled={busy}>승인하고 큐 실행</button><button type="button" className="rounded-lg border border-amber-300 px-3 py-2 text-xs font-bold text-amber-800" onClick={() => setApprovalPending(false)} disabled={busy}>취소</button></div></div>}{status && <p role="status" className="mt-3 text-sm text-emerald-700">{status}</p>}{error && <p role="alert" className="mt-3 text-sm text-rose-700">{error}</p>}</section>;
}

function FileTextPreview({ preview }: { preview: Extract<UserProjectWorkspaceFilePreview, { status: 'ready' }> }) {
  const lines = preview.content.split(/\r?\n/);
  return <pre className="mt-2 max-h-96 overflow-auto rounded-xl bg-slate-950 p-4 text-xs leading-6 text-slate-100" tabIndex={0} aria-label={`파일 내용 ${preview.path}`}><code>{lines.map((line, index) => <span key={`${preview.path}-${index}`} className="block"><span aria-label={`파일 줄 번호 ${index + 1}`} className="mr-4 inline-block min-w-[2ch] select-none text-right text-slate-500">{index + 1}</span>{line || ' '}</span>)}</code></pre>;
}

function diffLineClass(kind: UserProjectWorkspaceDiffLine['kind']): string {
  if (kind === 'addition') return 'bg-emerald-950/70 text-emerald-100';
  if (kind === 'deletion') return 'bg-rose-950/70 text-rose-100';
  return 'text-slate-200';
}

function DiffHunk({ hunk }: { hunk: UserProjectWorkspaceDiffHunk }) {
  return <section className="mt-3 overflow-hidden rounded-xl border border-slate-700 bg-slate-950"><h4 className="border-b border-slate-700 bg-slate-900 px-3 py-2 font-mono text-xs font-bold text-cyan-200">{hunk.header}</h4><div className="overflow-auto text-xs leading-6" tabIndex={0} aria-label={`변경사항 ${hunk.header}`}>{hunk.lines.map((line, index) => <div key={`${hunk.header}-${index}`} className={`grid min-w-[34rem] grid-cols-[4rem_4rem_1.5rem_minmax(0,1fr)] px-3 font-mono ${diffLineClass(line.kind)}`}><span className="select-none text-right text-slate-500">{line.oldLine ?? ''}</span><span className="select-none text-right text-slate-500">{line.newLine ?? ''}</span><span aria-label={line.kind === 'addition' ? '추가' : line.kind === 'deletion' ? '삭제' : '문맥'} className="select-none px-1 text-center font-black">{line.kind === 'addition' ? '+' : line.kind === 'deletion' ? '-' : ' '}</span><span className="whitespace-pre-wrap break-words">{line.text || ' '}</span></div>)}</div></section>;
}

function DiffPreview({ preview }: { preview: Extract<UserProjectWorkspaceFilePreview, { status: 'ready'; format: 'unified-diff' }> }) {
  return <div className="mt-2" aria-label={`변경사항 미리보기 ${preview.path}`}><div className="flex flex-wrap items-center gap-2 rounded-xl border border-violet-200 bg-violet-50 px-3 py-2 text-xs font-bold text-violet-900"><span>Unified diff</span><span className="text-emerald-700">+{preview.stats.additions} 추가</span><span className="text-rose-700">-{preview.stats.deletions} 삭제</span><span className="font-normal text-violet-700">읽기 전용</span></div>{preview.hunks.map((hunk) => <DiffHunk key={hunk.header} hunk={hunk} />)}</div>;
}

function ProjectFilesPanel({ view }: { view: UserProjectView }) {
  const files = view.workspace.files;
  const [selectedPath, setSelectedPath] = useState<string | null>(null);
  const [fileContent, setFileContent] = useState<UserProjectWorkspaceFilePreview | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const openFile = async (path: string) => {
    setSelectedPath(path); setFileContent(null); setError(''); setLoading(true);
    try { setFileContent(await getUserProjectFile(view.project.id, path)); }
    catch (caught) { setError(message(caught)); }
    finally { setLoading(false); }
  };
  return <section className="card-game p-5"><div className="mb-3"><h2 className="text-lg font-black text-slate-900">실제 작업공간 파일</h2><p className="mt-1 text-sm text-slate-600">실제 사용자 작업공간에서 확인된 파일만 표시합니다. 파일을 선택해야 제한된 읽기 전용 미리보기를 요청합니다.</p></div>{files.status === 'not-available' ? <p className="rounded-xl bg-amber-50 p-4 text-sm text-amber-800">작업공간 파일 목록을 확인할 수 없습니다. {files.blocker}</p> : files.items.length === 0 ? <p className="rounded-xl bg-slate-50 p-4 text-sm text-slate-500">아직 확인된 작업공간 파일이 없습니다.</p> : <div className="space-y-2">{files.items.map((file) => <div key={file.path} className="rounded-lg bg-slate-50 p-3 text-sm"><div className="flex items-center justify-between gap-3"><span className="min-w-0 break-all font-semibold text-slate-800">{file.path}</span><span className="shrink-0 text-xs text-slate-400">{file.size} B</span></div><button type="button" aria-label={`파일 열기 ${file.path}`} className="mt-2 rounded-lg border border-blue-200 px-3 py-1.5 text-xs font-bold text-blue-700 hover:bg-blue-50" onClick={() => void openFile(file.path)} disabled={loading && selectedPath === file.path}> {loading && selectedPath === file.path ? '불러오는 중…' : '파일 열기'}</button></div>)}{files.truncated && <p className="text-xs text-amber-700">파일이 많아 처음 500개까지만 표시합니다.</p>}</div>}{error && <p role="alert" className="mt-3 rounded-lg bg-rose-50 p-3 text-sm text-rose-700">{error}</p>}{selectedPath && loading && <p className="mt-3 text-xs text-slate-500">{selectedPath} 미리보기를 확인하는 중…</p>}{fileContent?.status === 'not-available' && <p role="status" className="mt-3 rounded-lg bg-amber-50 p-3 text-sm text-amber-800">이 파일은 미리보기할 수 없습니다. {fileContent.blocker}</p>}{fileContent?.status === 'ready' && <div className="mt-4"><div className="flex items-center justify-between gap-3"><h3 className="text-sm font-black text-slate-900">{fileContent.path}</h3><span className="text-xs text-slate-400">{fileContent.size} B · 읽기 전용</span>{'format' in fileContent && <span className="text-xs font-bold text-violet-700">변경사항 보기</span>}</div>{'format' in fileContent ? <DiffPreview preview={fileContent} /> : <FileTextPreview preview={fileContent} />}</div>}</section>;
}

export function ProjectWorkspace() {
  const profile = useUser(); const timezone = profile.status === 'ready' ? profile.timezone : undefined;
  const { id } = useParams<{ id: string }>(); const [view, setView] = useState<UserProjectView | null>(null); const [proposals, setProposals] = useState<AiTeamProposal[]>([]); const [discussions, setDiscussions] = useState<AiTeamDiscussion[]>([]); const [workspaceTab, setWorkspaceTab] = useState<WorkspaceTab>('overview'); const [loading, setLoading] = useState(true); const [title, setTitle] = useState(''); const [objective, setObjective] = useState(''); const [selectedDependencies, setSelectedDependencies] = useState<string[]>([]); const [error, setError] = useState<string | null>(null); const [approvalError, setApprovalError] = useState(''); const [buildRunApproval, setBuildRunApproval] = useState<boolean | null>(null); const [pendingStart, setPendingStart] = useState<string | null>(null); const [pendingResume, setPendingResume] = useState<string | null>(null); const [pendingRetry, setPendingRetry] = useState<string | null>(null); const [pendingPause, setPendingPause] = useState<string | null>(null); const [pendingCancel, setPendingCancel] = useState<string | null>(null); const [busy, setBusy] = useState(false);
  const refresh = useCallback(async () => { if (!id) return; setLoading(true); setError(null); setApprovalError(''); try { const nextView = await getUserProject(id); setView(nextView); try { setProposals((await listAiTeamProposals(id)).proposals); } catch { setProposals([]); } try { setDiscussions((await listAiTeamDiscussions(id)).discussions); } catch { setDiscussions([]); } try { setBuildRunApproval((await getSettings()).settings.aiApproval.buildRun); } catch { setBuildRunApproval(null); setApprovalError('실행 승인 상태를 확인할 수 없어 실행 요청을 잠시 보류합니다. 설정에서 다시 시도하세요.'); } } catch (nextError) { setError(message(nextError)); } finally { setLoading(false); } }, [id]);
  useEffect(() => { void refresh(); }, [refresh]);
  const addTask = async () => { if (!id || !title.trim() || !objective.trim()) { setError('작업 제목과 목적을 입력하세요.'); return; } setBusy(true); setError(null); try { await createProjectWorkRequest(id, { title: title.trim(), objective: objective.trim(), idempotencyKey: `${title.trim()}-${Date.now()}`, ...(selectedDependencies.length ? { dependencies: selectedDependencies } : {}) }); setTitle(''); setObjective(''); setSelectedDependencies([]); await refresh(); } catch (nextError) { setError(message(nextError)); } finally { setBusy(false); } };
  const toggleDependency = (workRequestId: string) => { setSelectedDependencies((current) => current.includes(workRequestId) ? current.filter((item) => item !== workRequestId) : [...current, workRequestId]); };
  const executeStart = async (workRequestId: string, approved = false) => { if (!id) return; setBusy(true); setError(null); setPendingStart(null); try { await startUserProjectRun(id, { workRequestId, runId: `user-run-${Date.now().toString(36)}`, ...(approved ? { approved: true } : {}) }); } catch (nextError) { setError(message(nextError)); } finally { await refresh(); setBusy(false); } };
  const executeResume = async (workRequestId: string, approved = false) => { if (!id) return; setBusy(true); setError(null); setPendingResume(null); try { await resumeUserProjectRun(id, { workRequestId, ...(approved ? { approved: true } : {}) }); } catch (nextError) { setError(message(nextError)); } finally { await refresh(); setBusy(false); } };
  const executeRetry = async (workRequestId: string, approved = false) => { if (!id) return; setBusy(true); setError(null); setPendingRetry(null); try { await retryUserProjectRun(id, { workRequestId, ...(approved ? { approved: true } : {}) }); } catch (nextError) { setError(message(nextError)); } finally { await refresh(); setBusy(false); } };
  const executePause = async (workRequestId: string) => { if (!id) return; setBusy(true); setError(null); setPendingPause(null); try { await pauseUserProjectRun(id, { workRequestId }); } catch (nextError) { setError(message(nextError)); } finally { await refresh(); setBusy(false); } };
  const executeCancel = async (workRequestId: string) => { if (!id) return; setBusy(true); setError(null); setPendingCancel(null); try { await cancelProjectWorkRequest(id, workRequestId); } catch (nextError) { setError(message(nextError)); } finally { await refresh(); setBusy(false); } };
  const start = (workRequestId: string) => { if (buildRunApproval === null) { setApprovalError('실행 승인 상태를 확인할 수 없어 실행 요청을 보류합니다.'); return; } if (buildRunApproval) { setPendingStart(workRequestId); return; } void executeStart(workRequestId); };
  const resume = (workRequestId: string) => { if (buildRunApproval === null) { setApprovalError('실행 승인 상태를 확인할 수 없어 재개 요청을 보류합니다.'); return; } if (buildRunApproval) { setPendingResume(workRequestId); return; } void executeResume(workRequestId); };
  const retry = (workRequestId: string) => { if (buildRunApproval === null) { setApprovalError('실행 승인 상태를 확인할 수 없어 재시도 요청을 보류합니다.'); return; } if (buildRunApproval) { setPendingRetry(workRequestId); return; } void executeRetry(workRequestId); };
  return <AppShell><div className="p-6 md:p-8" style={{ fontFamily: 'var(--font-body)' }}><Link to="/projects" className="text-sm font-semibold text-slate-400 no-underline">← 프로젝트 목록</Link>{loading ? <p className="mt-6 text-sm text-slate-500">프로젝트를 불러오는 중…</p> : !view || !id ? <div className="mt-6 card-game p-6 text-sm text-slate-500">프로젝트를 찾을 수 없습니다.</div> : <div className="mt-5 space-y-6"><div className="flex flex-wrap items-start justify-between gap-4"><div><h1 className="text-2xl font-black text-slate-900">{view.project.name}</h1><p className="mt-2 max-w-3xl text-sm text-slate-600">{view.project.objective}</p><p className="mt-2 text-xs text-slate-400">목적 {view.project.purpose} · 팀 {view.project.teamMode} · 사용자 소유 작업 공간</p></div><div className="flex items-center gap-3"><StatusBadge status={runtimeStatus(view.runtime.status)} /><Btn variant="secondary" onClick={() => void refresh()} disabled={busy}>새로고침</Btn></div></div>{error && <div role="alert" className="rounded-xl border-2 border-rose-200 bg-rose-50 p-4 text-sm font-semibold text-rose-700">{error}</div>}{approvalError && <div role="status" className="rounded-xl border-2 border-amber-200 bg-amber-50 p-4 text-sm font-semibold text-amber-800">{approvalError} <Link to="/settings" className="underline">AI 설정 확인</Link></div>}<MobileWorkspaceTabs activeTab={workspaceTab} onChange={setWorkspaceTab} /><WorkspacePanel tab="overview" activeTab={workspaceTab}><TeamTransition view={view} projectId={id} busy={busy} onChanged={refresh} onError={(nextError) => setError(message(nextError))} /><ExecutionProfilePanel view={view} /></WorkspacePanel><WorkspacePanel tab="evidence" activeTab={workspaceTab}><ProjectLifecyclePanel view={view} /><ProjectRunObservabilityPanel view={view} /><ProjectHistoryPanel view={view} /></WorkspacePanel><WorkspacePanel tab="ai" activeTab={workspaceTab}><AiCollaborationWorkspace projectId={id} teamMode={view.project.teamMode} teamId={view.project.teamId} proposals={proposals} discussions={discussions} busy={busy} onChanged={refresh} onError={(nextError) => setError(message(nextError))} /></WorkspacePanel>{pendingStart && <section className="card-game border-2 border-blue-200 bg-blue-50 p-5"><h2 className="mb-2 text-lg font-black text-slate-900">실행 승인 확인</h2><p className="text-sm text-slate-700">이 작업을 Runtime/Agent에 전달할 준비가 되었습니다. 확인하기 전에는 실행 요청을 보내지 않습니다.</p><div className="mt-4 flex flex-wrap gap-2"><Btn variant="mint" onClick={() => void executeStart(pendingStart, true)} disabled={busy}>승인하고 실행</Btn><Btn variant="secondary" onClick={() => setPendingStart(null)} disabled={busy}>승인 취소</Btn></div></section>}{pendingResume && <section className="card-game border-2 border-amber-200 bg-amber-50 p-5"><h2 className="mb-2 text-lg font-black text-slate-900">Run 재개 승인 확인</h2><p className="text-sm text-slate-700">기존 Run의 단계와 ID를 유지한 채 Runtime/Agent에 다시 전달합니다. 확인하기 전에는 재개 요청을 보내지 않습니다.</p><div className="mt-4 flex flex-wrap gap-2"><Btn variant="mint" onClick={() => void executeResume(pendingResume, true)} disabled={busy}>승인하고 재개</Btn><Btn variant="secondary" onClick={() => setPendingResume(null)} disabled={busy}>재개 취소</Btn></div></section>}{pendingRetry && <section className="card-game border-2 border-rose-200 bg-rose-50 p-5"><h2 className="mb-2 text-lg font-black text-slate-900">Run 재시도 승인 확인</h2><p className="text-sm text-slate-700">실패한 Run의 동일한 ID와 현재 단계에서 다시 시작합니다. 확인하기 전에는 재시도 요청을 보내지 않습니다.</p><div className="mt-4 flex flex-wrap gap-2"><Btn variant="mint" onClick={() => void executeRetry(pendingRetry, true)} disabled={busy}>승인하고 재시도</Btn><Btn variant="secondary" onClick={() => setPendingRetry(null)} disabled={busy}>재시도 취소</Btn></div></section>}{pendingPause && <section className="card-game border-2 border-amber-300 bg-amber-50 p-5" role="alertdialog" aria-label="Run 실행 중단 확인"><h2 className="mb-2 text-lg font-black text-slate-900">실행 중단 확인</h2><p className="text-sm text-slate-700">현재 단계의 다음 checkpoint에서 Run을 일시 중단합니다. 이미 실행 중인 OS 프로세스는 강제 종료하지 않습니다.</p><div className="mt-4 flex flex-wrap gap-2"><Btn variant="danger" onClick={() => void executePause(pendingPause)} disabled={busy}>실행 중단</Btn><Btn variant="secondary" onClick={() => setPendingPause(null)} disabled={busy}>중단하지 않기</Btn></div></section>}{pendingCancel && <section className="card-game border-2 border-slate-300 bg-slate-50 p-5" role="alertdialog" aria-label="작업 요청 취소 확인"><h2 className="mb-2 text-lg font-black text-slate-900">취소 확인</h2><p className="text-sm text-slate-700">아직 Run을 시작하지 않은 작업 요청만 취소합니다. 실행 중인 Run은 이 화면에서 강제 중단하지 않습니다.</p><div className="mt-4 flex flex-wrap gap-2"><Btn variant="danger" onClick={() => void executeCancel(pendingCancel)} disabled={busy}>작업 요청 취소</Btn><Btn variant="secondary" onClick={() => setPendingCancel(null)} disabled={busy}>취소하지 않기</Btn></div></section>}<div className="grid gap-6 xl:grid-cols-[1.1fr_0.9fr]"><WorkspacePanel tab="tasks" activeTab={workspaceTab}><section className="card-game p-5"><h2 className="mb-4 text-lg font-black text-slate-900">작업 요청</h2><p className="mb-4 text-xs text-slate-500">실행 전에는 요청을 취소할 수 있고, 실행 중에는 현재 단계 checkpoint에서 일시 중단할 수 있습니다. 이미 실행 중인 OS 프로세스는 강제 종료하지 않습니다.</p><div className="grid gap-3"><input aria-label="작업 제목" value={title} onChange={(event) => setTitle(event.target.value)} placeholder="작업 제목" className="rounded-xl border-2 border-blue-100 px-3 py-2.5 text-sm" /><textarea aria-label="작업 목적" value={objective} onChange={(event) => setObjective(event.target.value)} placeholder="작업의 완료 조건" rows={3} className="rounded-xl border-2 border-blue-100 px-3 py-2.5 text-sm" /><Btn variant="mint" onClick={() => void addTask()} disabled={busy}>작업 요청 저장</Btn></div><div className="mt-5 space-y-3">{view.workRequests.length === 0 ? <p className="rounded-xl bg-slate-50 p-4 text-sm text-slate-500">저장된 작업 요청이 없습니다.</p> : view.workRequests.map((request) => <div key={request.id} className="rounded-xl border-2 border-blue-100 p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-bold text-slate-900">{request.title}</p><p className="mt-1 text-sm text-slate-600">{request.objective}</p></div>{request.status === 'cancelled' ? <span className="inline-flex items-center rounded-full bg-slate-100 px-2 py-0.5 text-xs font-bold text-slate-500">취소됨</span> : <StatusBadge status={request.status === 'running' ? 'running' : request.status === 'completed' ? 'success' : request.status === 'failed' ? 'error' : request.status === 'waiting' ? 'warning' : 'pending'} />}</div>{request.blocker && <p className="mt-2 text-xs text-amber-700">{request.blocker}</p>}<div className="mt-3 flex flex-wrap gap-x-3 gap-y-1 text-xs text-slate-500"><span>요청 ID: {request.id}</span><span>시도 {request.attempts}회</span><span>생성 {date(request.createdAt, timezone)}</span>{request.runId && <span>Run ID: {request.runId}</span>}</div><div className="mt-3 flex justify-end gap-2">{request.status === 'queued' && <><Btn variant="secondary" size="sm" onClick={() => void start(request.id)} disabled={busy || buildRunApproval === null}>{buildRunApproval === null ? '승인 상태 확인 중…' : buildRunApproval ? '승인 후 실행' : '실행 요청'}</Btn><Btn variant="danger" size="sm" onClick={() => setPendingCancel(request.id)} disabled={busy}>요청 취소</Btn></>}{request.status === 'running' && request.runId && <Btn variant="danger" size="sm" onClick={() => setPendingPause(request.id)} disabled={busy}>실행 중단</Btn>}{request.status === 'waiting' && request.runId && <Btn variant="secondary" size="sm" onClick={() => resume(request.id)} disabled={busy || buildRunApproval === null}>{buildRunApproval === null ? '승인 상태 확인 중…' : buildRunApproval ? '승인 후 재개' : 'Run 재개'}</Btn>}{request.status === 'failed' && request.runId && <Btn variant="secondary" size="sm" onClick={() => retry(request.id)} disabled={busy || buildRunApproval === null}>{buildRunApproval === null ? '승인 상태 확인 중…' : buildRunApproval ? '승인 후 재시도' : '재시도'}</Btn>}</div></div>)}</div></section><ProjectStructurePanel view={view} /><ProjectFilesPanel view={view} /></WorkspacePanel><WorkspacePanel tab="evidence" activeTab={workspaceTab}><section className="space-y-6"><div className="card-game p-5"><h2 className="mb-3 text-lg font-black text-slate-900">Runtime 상태</h2><p className="text-sm text-slate-600">{view.runtime.status === 'not-started' ? '아직 실행된 Run이 없습니다.' : view.runtime.blocker ?? `Run ${view.runtime.runId ?? 'unknown'} · ${view.runtime.stage ?? view.runtime.status}`}</p><p className="mt-3 text-xs text-slate-400">실제 Runtime/Agent 근거가 연결될 때만 Artifact·Revision·Deployment 상태가 표시됩니다.</p></div><div className="card-game p-5"><h2 className="mb-3 text-lg font-black text-slate-900">검증된 증거</h2>{view.evidence.length === 0 ? <p className="text-sm text-slate-500">아직 검증된 실행 증거가 없습니다.</p> : <div className="space-y-2">{view.evidence.map((item) => <div key={item.id} className="rounded-lg bg-emerald-50 p-3 text-sm text-emerald-900"><span className="font-bold">{item.kind}</span> · {item.stage} — {item.summary}</div>)}</div>}</div></section></WorkspacePanel></div></div>}</div></AppShell>;
}
